local _, WFJ = ...
WFJ.Data.add("book", {
  ["d51a1fc86d3e8f2e"] = { "Molte tribù sostengono che sia un dono essere benedetti dall'attitudine a usare la magia o a parlare con i nostri antenati, ma devi sapere anche questo, {class}: i tuoi doni non sono da meno. Alcuni non hanno nelle braccia la forza di brandire armi possenti. Alcuni non hanno l'abilità di parare il colpo di un assassino, né di sopportare le punizioni fisiche di un incantatore arcano, ma tu sì. Tu hai forza. E io ti aiuterò ad averne ancora di più. Cercami a ⟦Camp Narache=Campo Narache⟧.\n\n-Harutt Thunderhorn, istruttore dei guerrieri", "." },
  ["d522e0d11cfe0990"] = { "Non smette mai di stupirmi quanto sia facile usare l'odio per piegare gli altri alla propria volontà. Orchi e troll sono stati i più facili: il loro odio per l'⟦Alliance=Alleanza⟧ li ha resi sudditi ben disposti ad ascoltare il messaggio del Dark Strand. Hanno la minima idea del potere più grande che servono?\n\nQuell'insopportabile paladino, Delgren il Purificatore, ficca il naso nei nostri affari nella foresta di ⟦Ashenvale=Valtetra⟧, mentre il suo tirapiedi, Balthule, spia la mia torre, convinto che io non sappia della sua presenza. Delgren ci ritiene una", "." },
  ["d528444634c9ae32"] = { "Nessuno sa con esattezza come ebbe inizio l'universo. Alcuni ipotizzano che una catastrofica esplosione cosmica abbia scagliato gli infiniti mondi nella vastità della Grande Oscurità: mondi che un giorno avrebbero ospitato forme di vita di una diversità meravigliosa e terribile. Altri credono che l'universo, così com'è, sia stato creato nella sua interezza da un'unica entità onnipotente.", "." },
  ["d5599f9ad85d5592"] = { "C'è stata un'eccezione. I curiosi idoli scolpiti trovati di recente (ne ho incluso una breve descrizione nel mio ultimo rapporto) sembrano avere un effetto sui trogg del sito. Sono attratti dalle sculture di pietra, e alcuni trogg ne vengono fatti impazzire di furia!\n\nServono altri studi per trarre qualsiasi conclusione su questi idoli, ma resto fiducioso che getteranno luce su un legame tra i trogg e i Titani.", "." },
  ["d55d70f46227bda3"] = { "Tutto inutile, a quanto pare..\n\nPochi istanti dopo la sacerdotessa viene sommersa dai cadaveri dei contadini che la circondavano....\n\nI caduti si sono rialzati.", "." },
  ["d5c7222fa6c04149"] = { "Uldaman, giorno 4\n\n...il primo indizio si è rivelato nelle profondità di Uldaman: uno dei trogg più selvaggi che abbia mai visto brandiva un grosso zaffiro, uno che scommetto si adatterebbe perfettamente alla collana. Ho sentito uno dei nani Forgiascura pronunciare il nome della bestia: ⟦Grimlok=Tetrok⟧. La schiera di guardiani di questo bruto di ⟦Grimlok=Tetrok⟧, però...", "." },
  ["d5d1ffa8487a9e5e"] = { "I draghi osservavano un flusso infinito di silitidi e Qiraji riversarsi fuori da ⟦Ahn'Qiraj=Ahn'qiraj⟧. Divenne loro chiaro che nessuna forza avrebbe mai potuto porre fine a questa guerra. All'interno del tempio principale attendevano decine di migliaia di soldati Qiraji. A ogni secondo che passava, altri ne nascevano e venivano preparati, pronti a essere scatenati sul mondo.", "." },
  ["d5feeb991dd1a05b"] = { "Ho inviato un altro messaggero a Dalaran, e sento dire che anche ora lo stanno cercando tra le rovine fuori dalla nostra sfera protettiva.\n\nSpero solo che non sia troppo tardi.", "." },
})
